import{a as e,c as t,i as n,t as r}from"./app-C4mzCnKe.js";var i=JSON.parse(`{"path":"/roadmap.html","title":"落地路线（先判决器，后决策面）","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"roadmap.md"}`),a={name:`roadmap.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="落地路线-先判决器-后决策面" tabindex="-1"><a class="header-anchor" href="#落地路线-先判决器-后决策面"><span>落地路线（先判决器，后决策面）</span></a></h1><p>「可观测」与「自进化」两条纵贯线<strong>从 P0 就贯穿，不是到最后才加</strong>：判决器（冻结层）先立，观测底座同步铺，进化门禁随评测平台一起落地。</p><table><thead><tr><th>阶段</th><th>做什么</th><th>完成判据</th><th>可观测纵贯线</th><th>自进化纵贯线</th></tr></thead><tbody><tr><td>P0 判决器</td><td>回测判决官 + 对账官 + 数据口径契约 + Trace 总线</td><td>oracle 测试能识别正 alpha；独立日 ≥30；配对检验可用</td><td>Trace 总线 + 三层语义 + 四元 id + 前缀门禁</td><td>冻结层先立（判决器/口径/回测引擎）</td></tr><tr><td>P1 资产</td><td>数据管家、知识馆长、能力管家、协议注册表</td><td>口径注册率 100%；知识卡带证据等级；未考证数据拒入</td><td>检索 / 取数 span 入总线</td><td>可进化 B（知识卡/口径/skill）就位</td></tr><tr><td>P2 决策面 + 主控</td><td>主控、调度器、策略师、因子工坊、大盘分析师、盘中哨兵</td><td>主控规划可落地；proposal 可被判决官直接消费</td><td>8 类 Span 全覆盖；决策包带概率置信度</td><td>可进化 A（策略/因子）就位，因子 4 类动作可执行</td></tr><tr><td>P3 评测平台</td><td>采集/评测/反馈三层 + 过程资产 + 会话评估官 + 影子回放门禁</td><td>任意决策可回放；A/B 回归门禁生效</td><td>三阶段评估 + 定向观测 + logprobs 置信度</td><td>影子回放门禁 + 三重门控 + 溯源图归因</td></tr><tr><td>P4 自我进化</td><td>全链路闭环</td><td>过程变更皆有证据，更差自动回滚</td><td>token 级 trace + 指标归因 + 实验</td><td>意图-经验-效用 + 效用检索 + 双环闭环</td></tr></tbody></table><blockquote><p>每阶段的「完成判据」都同时含一条观测判据和一条进化判据，缺一不算该阶段完成——这正是「横切」的含义：两条线不是附加项，而是每个阶段的验收标准。</p></blockquote>`,4)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};